{"filePath":"/Users/dk/lab-data/oleovista-acers/acers-web/src/Helpers/date.helper.ts","oldString":"export const zeroPad2 = (value: number): string => (value < 10 ? '0' + value : String(value));

export const formatDateForAPIFromDate = (date: Date): string => {

    if (Number.isNaN(date.getTime())) {

        console.warn('formatDateForAPIFromDate failed to parse date', date);
        return '';
    }

    const day: string = zeroPad2(date.getDate());
    const month: string = zeroPad2(date.getMonth() + 1);
    const year: number = date.getFullYear();
    const formattedDate: string = `${day}-${month}-${year}`;

    return formattedDate;
};

export const formatDateForAPI = (dateInput: string): string => {
    if (!dateInput) {
        console.warn('formatDateForAPI called with empty dateInput');
        return '';
    }

    const trimmed = dateInput.trim();
    const isoMatch = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/.exec(trimmed);
    if (isoMatch) {
        return `${isoMatch[3]}-${isoMatch[2]}-${isoMatch[1]}`;
    }

    const date: Date = new Date(trimmed);
    return formatDateForAPIFromDate(date);
};
","newString":"const ISO_DATE_HYPHEN_RE = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;

export const zeroPad2 = (value: number): string => (value < 10 ? '0' + value : String(value));

export const formatDateForAPIFromDate = (date: Date): string => {

    if (Number.isNaN(date.getTime())) {

        console.warn('formatDateForAPIFromDate failed to parse date', date);
        return '';
    }

    const day: string = zeroPad2(date.getDate());
    const month: string = zeroPad2(date.getMonth() + 1);
    const year: number = date.getFullYear();
    const formattedDate: string = `${day}-${month}-${year}`;

    return formattedDate;
};

export const formatDateForAPI = (dateInput: string): string => {
    if (!dateInput) {
        console.warn('formatDateForAPI called with empty dateInput');
        return '';
    }

    const trimmed = dateInput.trim();
    const isoMatch = ISO_DATE_HYPHEN_RE.exec(trimmed);
    if (isoMatch) {
        return `${isoMatch[3]}-${isoMatch[2]}-${isoMatch[1]}`;
    }

    const date: Date = new Date(trimmed);
    return formatDateForAPIFromDate(date);
};
"}

{"filePath":"/Users/dk/lab-data/oleovista-acers/acers-web/src/Helpers/date.helper.ts","oldString":"export const normalizeToYMD = (d: Date | string | null): string | null => {
    if (!d) {
        return null;
    }

    if (typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d)) {
        return d;
    }

    const date = new Date(d);
    if (Number.isNaN(date.getTime())) {
        return null;
    }

    return formatYMD(date);
};
","newString":"export const normalizeToYMD = (d: Date | string | null): string | null => {
    if (!d) {
        return null;
    }

    if (typeof d === 'string' && ISO_DATE_HYPHEN_RE.test(d)) {
        return d;
    }

    const date = new Date(d);
    if (Number.isNaN(date.getTime())) {
        return null;
    }

    return formatYMD(date);
};
