{"filePath":"/Users/dk/lab-data/oleovista-acers/acers-web/benchmarks/bench-date.js","content":"const { formatFromYYYYMMDD, formatFromYYYYMMDDSlash, formatFromDDMMYYYY, formatFromEpoch, formatDateForAPI } = require('../src/Helpers/date.helper');

function bench(name, fn, iterations = 200000) {
  const inputs = [];
  for (let i = 0; i < iterations; i++) {
    // mix inputs to exercise micro-paths
    if (i % 4 === 0) inputs.push('2024-12-31');
    else if (i % 4 === 1) inputs.push('2024/12/31');
    else if (i % 4 === 2) inputs.push('31-12-2024');
    else inputs.push(String(1712121600 + i)); // epoch seconds-ish
  }

  const start = process.hrtime.bigint();
  for (const s of inputs) fn(s);
  const end = process.hrtime.bigint();
  const ms = Number(end - start) / 1e6;
  console.log(`${name}: ${ms.toFixed(2)} ms`);
}

// Handler-only: call the specific exported handler based on heuristic
bench('handlers-direct (switch)', (s) => {
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return formatFromYYYYMMDD(s);
  if (/^\d{4}\/\d{2}\/\d{2}$/.test(s)) return formatFromYYYYMMDDSlash(s);
  if (/^\d{2}-\d{2}-\d{4}$/.test(s)) return formatFromDDMMYYYY(s);
  return formatFromEpoch(s);
});

// Handler chain: try each handler sequentially (like previous impl)
bench('handlers-chain', (s) => {
  let out = formatFromYYYYMMDD(s);
  if (out) return out;
  out = formatFromYYYYMMDDSlash(s);
  if (out) return out;
  out = formatFromDDMMYYYY(s);
  if (out) return out;
  return formatFromEpoch(s);
});

// General parse path: formatDateForAPI (single Date constructor)
bench('general-parse', (s) => formatDateForAPI(s));

// Mixed: callers that sometimes call handler then fallback
bench('mixed (call handler then fallback if null)', (s) => {
  const out = formatFromYYYYMMDD(s) || formatFromYYYYMMDDSlash(s) || formatFromDDMMYYYY(s) || formatFromEpoch(s);
  if (out) return out;
  return formatDateForAPI(s);
});
